$(function(){$("table").on("accountSelected","input[data-type='search_account']",function(){const closestRow=$(this).closest("tr");const accountId=$(this).attr("data-ac-id");ChartOfAccount.getCurrencyRate(closestRow.find("[data-js='currency_rate']"),accountId,true);ChartOfAccount.getAccountBalance(closestRow.find(".balance"),accountId,false)}).on("change","input[data-type='int'], input[data-type='float']",function(){$("[data-type='int'], [data-type='float']").each(function(){if($(this).val()==="")$(this).val(0)});var total_debit=0;var total_credit=0;var s_no=0;$("table.dynamic tbody tr").each(function(){$(".s_no",this).html(++s_no);var debit=NumberHelper.parseInput($("[data-js='debit']",this));var credit=NumberHelper.parseInput($("[data-js='credit']",this));total_debit+=isNaN(debit)?0:debit;total_credit+=isNaN(credit)?0:credit});$(".total_debit").html(NumberHelper.thousandSep(total_debit));$(".total_credit").html(NumberHelper.thousandSep(total_credit))});$("form").submit(function(){var total_debit=parseFloat(NumberHelper.clearThousandSep($('[data-input-sum="[data-js=debit]"]').html()));var total_credit=parseFloat(NumberHelper.clearThousandSep($('[data-input-sum="[data-js=credit]"]').html()));if(total_credit!==total_debit){ErrorHandler.initError();ErrorHandler.setError("Debit and Credit are not equal");ErrorHandler.showError();return false}else{FormHelper.nameToIdConvert();return true}});if($("#voucher_id").length)$("table input[data-type='float']:first-child").trigger("change")});